//! Colour themes (themes/*.json), compiled in.
//! Each family (harlo, Dracula, Nord…) has a dark and a light variant.

use std::sync::OnceLock;

use serde_json::Value;

// `THEME_FILES`: the theme JSON files' contents (generated by build.rs).
include!(concat!(env!("OUT_DIR"), "/themes.rs"));

pub const DEFAULT_FAMILY: &str = "harlo";

pub struct ThemeInfo {
    pub family: String,
    pub variant: String,
    /// The theme JSON with colours in Qt's `#AARRGGBB` order.
    pub json: String,
    colors: Value,
}

fn all() -> &'static [ThemeInfo] {
    static THEMES: OnceLock<Vec<ThemeInfo>> = OnceLock::new();
    THEMES.get_or_init(|| {
        let mut out: Vec<ThemeInfo> = THEME_FILES
            .iter()
            .filter_map(|text| {
                let mut v: Value = serde_json::from_str(text).ok()?;
                qt_colors(&mut v);
                let meta = &v["metadata"];
                let variant = meta["variant"].as_str()?.to_owned();
                let name = meta["name"].as_str()?;
                // "Cursor Dark" / "Cursor Light" belong to one family.
                let family = name.strip_suffix(" Dark").or_else(|| name.strip_suffix(" Light")).unwrap_or(name).to_owned();
                Some(ThemeInfo { family, variant, json: v.to_string(), colors: v["colors"].clone() })
            })
            .collect();
        out.sort_by(|a, b| a.family.to_lowercase().cmp(&b.family.to_lowercase()).then(a.variant.cmp(&b.variant)));
        out
    })
}

/// CSS `#RRGGBBAA` → Qt `#AARRGGBB`; other values untouched.
fn qt_colors(v: &mut Value) {
    match v {
        Value::String(s) if s.len() == 9 && s.starts_with('#') && s[1..].chars().all(|c| c.is_ascii_hexdigit()) => {
            *s = format!("#{}{}", &s[7..9], &s[1..7]);
        }
        Value::Object(map) => map.values_mut().for_each(qt_colors),
        Value::Array(items) => items.iter_mut().for_each(qt_colors),
        _ => {}
    }
}

/// The theme for a family and variant ("dark" / "light"), falling back to
/// the other variant, then to the default family.
pub fn find(family: &str, variant: &str) -> &'static ThemeInfo {
    let themes = all();
    themes
        .iter()
        .find(|t| t.family == family && t.variant == variant)
        .or_else(|| themes.iter().find(|t| t.family == family))
        .or_else(|| themes.iter().find(|t| t.family == DEFAULT_FAMILY && t.variant == variant))
        .unwrap_or(&themes[0])
}

/// One line per family: `family\tdark\tlight`, where each variant is
/// `background,foreground,primary,elevated,mutedForeground,sidebar` (empty
/// if missing), for the picker's previews.
pub fn families() -> Vec<String> {
    let preview = |family: &str, variant: &str| {
        all().iter().find(|t| t.family == family && t.variant == variant).map_or(String::new(), |t| {
            let c = &t.colors;
            [&c["surface"]["background"], &c["surface"]["foreground"], &c["primary"]["base"], &c["surface"]["elevated"], &c["surface"]["mutedForeground"], &c["surface"]["muted"]]
                .iter()
                .map(|v| v.as_str().unwrap_or(""))
                .collect::<Vec<_>>()
                .join(",")
        })
    };
    let mut seen = Vec::<&str>::new();
    for t in all() {
        if !seen.contains(&t.family.as_str()) {
            seen.push(&t.family);
        }
    }
    seen.iter().map(|f| format!("{f}\t{}\t{}", preview(f, "dark"), preview(f, "light"))).collect()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn loads_every_theme() {
        assert_eq!(all().len(), THEME_FILES.len(), "every theme file parses");
        let families = families();
        assert!(families.len() >= 29, "{}", families.len());
        assert!(families.iter().any(|f| f.starts_with("Cursor\t")));
        // Every family has both variants with the colours the UI reads.
        for t in all() {
            for key in [("surface", "background"), ("surface", "foreground"), ("primary", "base"), ("status", "error")] {
                assert!(t.colors[key.0][key.1].is_string(), "{} {} lacks {key:?}", t.family, t.variant);
            }
        }
        let oc = find("Ember", "dark");
        assert!(oc.json.contains("\"#80da7c47\""), "alpha moves to the front");
        assert_eq!(find("Nope", "light").family, DEFAULT_FAMILY);
        assert_eq!(find(DEFAULT_FAMILY, "light").variant, "light", "harlo's own theme has both");
        assert_eq!(find("Dracula", "light").variant, "light");
    }
}
